/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyFoodExpenseOverage exports=analyzeMonthlyFoodExpenseOverage */
const __aivicBundle_3_analyzeMonthlyFoodExpenseOverage = (() => {
  function analyzeMonthlyFoodExpenseOverage(
    input: FoodExpenseOverageInput
  ): FoodExpenseOverageResult {
    const {
      budget_limit,
      actual_expense,
      purchase_records,
      baseline_budget_reference_month_expense,
    } = input;
  
    const total_overage_amount = actual_expense - budget_limit;
    const budget_status = actual_expense > budget_limit ? "exceeded" : "within";
  
    // Group purchase records by category and calculate baseline vs actual
    const categoryMap = new Map<
      string,
      {
        baseline_expense: number;
        actual_expense: number;
        baseline_quantity: number;
        actual_quantity: number;
        baseline_unit_price: number;
        actual_unit_price: number;
      }
    >();
  
    for (const record of purchase_records) {
      const category = record.category || "other";
      const actual_cost = record.quantity * record.unit_price;
      const baseline_cost = record.quantity * record.baseline_unit_price;
  
      if (!categoryMap.has(category)) {
        categoryMap.set(category, {
          baseline_expense: 0,
          actual_expense: 0,
          baseline_quantity: 0,
          actual_quantity: 0,
          baseline_unit_price: 0,
          actual_unit_price: 0,
        });
      }
  
      const cat = categoryMap.get(category)!;
      cat.baseline_expense += baseline_cost;
      cat.actual_expense += actual_cost;
      cat.baseline_quantity += record.quantity;
      cat.actual_quantity += record.quantity;
      cat.baseline_unit_price = record.baseline_unit_price;
      cat.actual_unit_price = record.unit_price;
    }
  
    // Build category breakdown
    const category_breakdown: CategoryBreakdown[] = Array.from(
      categoryMap.entries()
    ).map(([category_name, data]) => ({
      category_name,
      baseline_expense: data.baseline_expense,
      actual_expense: data.actual_expense,
    }));
  
    // Calculate total baseline and actual from records
    const total_baseline_from_records = Array.from(categoryMap.values()).reduce(
      (sum, cat) => sum + cat.baseline_expense,
      0
    );
    const total_actual_from_records = Array.from(categoryMap.values()).reduce(
      (sum, cat) => sum + cat.actual_expense,
      0
    );
  
    // Composition effect: change in quantity/mix at baseline prices
    const composition_variation_effect =
      total_actual_from_records - total_baseline_from_records;
  
    // Unit price variation effect: the difference between actual and baseline unit prices
    // applied to actual quantities
    let unit_price_variation_effect = 0;
    for (const record of purchase_records) {
      const price_delta = record.unit_price - record.baseline_unit_price;
      unit_price_variation_effect += price_delta * record.quantity;
    }
  
    // Other factors: residual difference accounting for structural changes in spending patterns
    // This includes the delta between the baseline reference month and the actual records,
    // plus any remaining unexplained variance
    const baseline_to_records_delta =
      total_baseline_from_records - baseline_budget_reference_month_expense;
    const other_factors_effect =
      total_overage_amount -
      composition_variation_effect -
      unit_price_variation_effect -
      baseline_to_records_delta;
  
    // Calculate percentages based on absolute values
    const total_effect =
      Math.abs(composition_variation_effect) +
      Math.abs(unit_price_variation_effect) +
      Math.abs(other_factors_effect);
  
    let composition_variation_percentage = 0;
    let unit_price_variation_percentage = 0;
    let other_factors_percentage = 0;
  
    if (total_effect > 0) {
      composition_variation_percentage = Math.round(
        (Math.abs(composition_variation_effect) / total_effect) * 100
      );
      unit_price_variation_percentage = Math.round(
        (Math.abs(unit_price_variation_effect) / total_effect) * 100
      );
      other_factors_percentage = Math.round(
        (Math.abs(other_factors_effect) / total_effect) * 100
      );
    } else if (total_overage_amount !== 0) {
      // When there's overage but no composition/price variation detected
      other_factors_percentage = 100;
    }
  
    const analysis_timestamp = new Date().toISOString();
  
    const export_csv_format = (): string => {
      const headers = [
        "Category",
        "Baseline Expense",
        "Actual Expense",
        "Variance",
      ];
      const rows = category_breakdown.map((cat) => [
        cat.category_name,
        cat.baseline_expense.toString(),
        cat.actual_expense.toString(),
        (cat.actual_expense - cat.baseline_expense).toString(),
      ]);
  
      const csvContent = [
        headers.join(","),
        ...rows.map((row) => row.join(",")),
        "",
        "Analysis Summary",
        `Total Overage Amount,${total_overage_amount}`,
        `Composition Variation Effect,${composition_variation_effect}`,
        `Unit Price Variation Effect,${unit_price_variation_effect}`,
        `Other Factors Effect,${other_factors_effect}`,
        `Composition Variation %,${composition_variation_percentage}`,
        `Unit Price Variation %,${unit_price_variation_percentage}`,
        `Other Factors %,${other_factors_percentage}`,
      ].join("\n");
  
      return csvContent;
    };
  
    return {
      total_overage_amount,
      composition_variation_effect,
      unit_price_variation_effect,
      other_factors_effect,
      composition_variation_percentage,
      unit_price_variation_percentage,
      other_factors_percentage,
      category_breakdown,
      export_csv_format,
      analysis_status: "success",
      analysis_timestamp,
      budget_status,
    };
  }
  return { analyzeMonthlyFoodExpenseOverage };
})();
