const __aivicBundle_9_calculateEstimatedFoodCost = (() => {
  function calculateEstimatedFoodCost(input: CalculateEstimatedCostInput): number {
    const { daily_menus, ingredient_prices, family_size } = input;
  
    let total_cost = 0;
  
    if (!daily_menus || daily_menus.length === 0) {
      return 0;
    }
  
    if (!ingredient_prices || Object.keys(ingredient_prices).length === 0) {
      return 0;
    }
  
    for (const daily_menu of daily_menus) {
      if (!daily_menu.meals || daily_menu.meals.length === 0) {
        continue;
      }
  
      for (const meal of daily_menu.meals) {
        if (!meal.ingredients || meal.ingredients.length === 0) {
          continue;
        }
  
        for (const ingredient_id of meal.ingredients) {
          const unit_price = ingredient_prices[ingredient_id];
          if (unit_price !== undefined && unit_price !== null) {
            total_cost += unit_price;
          }
        }
      }
    }
  
    return Math.ceil((total_cost / daily_menus.length) * family_size);
  }
  return { calculateEstimatedFoodCost };
})();
export const calculateEstimatedFoodCost = __aivicBundle_9_calculateEstimatedFoodCost.calculateEstimatedFoodCost;
