/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyExpenseBreakdown exports=analyzeMonthlyExpenseBreakdown */
const __aivicBundle_10_analyzeMonthlyExpenseBreakdown = (() => {
  function analyzeMonthlyExpenseBreakdown(
    input: AnalyzeExpenseBreakdownInput
  ): AnalyzeExpenseBreakdownResult {
    // Normalize input: support both flat products array and nested baseline_month/test_month structures
    let baselineProducts: Array<{
      id: string;
      base_price: number;
      quantity: number;
    }> = [];
    let testProducts: Array<{
      id: string;
      test_price: number;
      quantity: number;
    }> = [];
  
    // Extract from nested structure if present
    if (input.baseline_month && "products" in input.baseline_month) {
      baselineProducts = (
        input.baseline_month as {
          products: Array<{ id: string; base_price: number; quantity: number }>;
        }
      ).products;
    }
    if (input.test_month && "products" in input.test_month) {
      testProducts = (
        input.test_month as {
          products: Array<{ id: string; test_price: number; quantity: number }>;
        }
      ).products;
    }
  
    // If products array is provided at top level, use it as source of truth
    if (input.products && input.products.length > 0) {
      baselineProducts = input.products.map((p) => ({
        id: p.id,
        base_price: p.base_price,
        quantity: p.quantity,
      }));
      testProducts = input.products.map((p) => ({
        id: p.id,
        test_price: p.test_price,
        quantity: p.quantity,
      }));
    }
  
    // Calculate per-product variance
    const breakdownByProduct: BreakdownByProduct[] = [];
    let totalExcessByUnitPrice = 0;
    let cumulativeExcess = 0;
    let totalVariance = 0;
  
    // Create maps for quick lookup
    const baselineMap = new Map(baselineProducts.map((p) => [p.id, p]));
    const testMap = new Map(testProducts.map((p) => [p.id, p]));
  
    // Process all products from both baseline and test
    const allProductIds = new Set([
      ...baselineMap.keys(),
      ...testMap.keys(),
    ]);
  
    for (const productId of allProductIds) {
      const baseProduct = baselineMap.get(productId);
      const testProduct = testMap.get(productId);
  
      if (!baseProduct || !testProduct) {
        continue;
      }
  
      const basePrice = baseProduct.base_price;
      const testPrice = testProduct.test_price;
      const quantity = baseProduct.quantity;
  
      // Calculate per-unit price variance
      const unitPriceVariance = testPrice - basePrice;
  
      // Calculate excess amount for this product
      const excessAmount = unitPriceVariance * quantity;
  
      // Calculate variance percentage (as percentage, not decimal)
      const variancePercentage =
        basePrice !== 0 ? (unitPriceVariance / basePrice) * 100 : 0;
  
      breakdownByProduct.push({
        product_id: productId,
        excess_amount: excessAmount,
        variance_percentage: variancePercentage,
      });
  
      totalExcessByUnitPrice += excessAmount;
      cumulativeExcess += excessAmount;
      totalVariance += unitPriceVariance;
    }
  
    // Calculate overall unit price variance (average across all products)
    const overallUnitPriceVariance =
      breakdownByProduct.length > 0
        ? totalVariance / breakdownByProduct.length
        : 0;
  
    // Calculate overall variance percentage
    const totalBaselineValue = Array.from(baselineMap.values()).reduce(
      (sum, p) => sum + p.base_price * p.quantity,
      0
    );
    const overallVariancePercentage =
      totalBaselineValue !== 0
        ? (totalExcessByUnitPrice / totalBaselineValue) * 100
        : 0;
  
    const result: AnalyzeExpenseBreakdownResult = {
      unit_price_variance: overallUnitPriceVariance,
      variance_percentage: overallVariancePercentage,
      total_excess_by_unit_price: totalExcessByUnitPrice,
      cumulative_excess: cumulativeExcess,
      breakdown_by_product: breakdownByProduct,
      export_report: (options: { format: string; precision?: number }) => {
        const precision = options.precision ?? 2;
        return {
          unit_price_variance: parseFloat(
            overallUnitPriceVariance.toFixed(precision)
          ),
          variance_percentage: parseFloat(
            overallVariancePercentage.toFixed(precision)
          ),
          total_excess_by_unit_price: parseFloat(
            totalExcessByUnitPrice.toFixed(precision)
          ),
        };
      },
    };
  
    return result;
  }
  return { analyzeMonthlyExpenseBreakdown };
})();
export const analyzeMonthlyExpenseBreakdown = __aivicBundle_10_analyzeMonthlyExpenseBreakdown.analyzeMonthlyExpenseBreakdown;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeMonthlyExpenseBreakdown */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMenuOptimizationScores exports=calculateMenuOptimizationScores */
const __aivicBundle_11_calculateMenuOptimizationScores = (() => {
  function calculateMenuOptimizationScores(
    input: MenuOptimizationScoresInput
  ): MenuOptimizationScoresResult {
    const { menu_proposals, inventory_price_data } = input;
  
    const scores: MenuScore[] = [];
  
    for (const menu of menu_proposals) {
      let totalSeasonalityScore = 0;
      let totalDiscountScore = 0;
      let totalInventorySatisfactionScore = 0;
      let ingredientCount = 0;
  
      for (const ingredient of menu.ingredients) {
        const priceData = inventory_price_data[ingredient.ingredient_id];
  
        if (priceData) {
          const seasonalityScore = (ingredient.season_relevance ?? 0) * 100;
          const discountScore = (priceData.discount_rate ?? 0) * 100;
          const inventorySatisfactionScore =
            (priceData.inventory_satisfaction ?? 0) * 100;
  
          totalSeasonalityScore += seasonalityScore;
          totalDiscountScore += discountScore;
          totalInventorySatisfactionScore += inventorySatisfactionScore;
          ingredientCount += 1;
        }
      }
  
      const avgSeasonalityScore =
        ingredientCount > 0 ? totalSeasonalityScore / ingredientCount : 0;
      const avgDiscountScore =
        ingredientCount > 0 ? totalDiscountScore / ingredientCount : 0;
      const avgInventorySatisfactionScore =
        ingredientCount > 0 ? totalInventorySatisfactionScore / ingredientCount : 0;
  
      const seasonalityWeight = 0.35;
      const discountWeight = 0.25;
      const inventorySatisfactionWeight = 0.4;
  
      const combinedScore =
        avgSeasonalityScore * seasonalityWeight +
        avgDiscountScore * discountWeight +
        avgInventorySatisfactionScore * inventorySatisfactionWeight;
  
      scores.push({
        seasonality_score: Math.round(avgSeasonalityScore * 100) / 100,
        discount_score: Math.round(avgDiscountScore * 100) / 100,
        inventory_satisfaction_score:
          Math.round(avgInventorySatisfactionScore * 100) / 100,
        combined_score: Math.round(combinedScore * 100) / 100
      });
    }
  
    const ranking: MenuRanking[] = menu_proposals
      .map((menu, index) => ({
        menu_id: menu.menu_id,
        combined_score: scores[index].combined_score
      }))
      .sort((a, b) => b.combined_score - a.combined_score);
  
    const uniqueIngredientIds = new Set<string>();
    for (const menu of menu_proposals) {
      for (const ingredient of menu.ingredients) {
        uniqueIngredientIds.add(ingredient.ingredient_id);
      }
    }
  
    return {
      scores,
      ranking,
      optimization_timestamp: new Date().toISOString(),
      data_source_count: menu_proposals.length,
      calculation_method: 'weighted_average',
      weighting_factors: {
        seasonality_weight: 0.35,
        discount_weight: 0.25,
        inventory_satisfaction_weight: 0.4
      }
    };
  }
  return { calculateMenuOptimizationScores };
})();
export const calculateMenuOptimizationScores = __aivicBundle_11_calculateMenuOptimizationScores.calculateMenuOptimizationScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMenuOptimizationScores */

/* AIVIC_FUNCTION_BUNDLE_START owner=fetchOptimalMenuWithFallback exports=fetchOptimalMenuWithFallback */
const __aivicBundle_12_fetchOptimalMenuWithFallback = (() => {
  async function fetchOptimalMenuWithFallback(
    input: FetchOptimalMenuInput
  ): Promise<FetchOptimalMenuResult> {
    const {
      user_id,
      family_ids,
      menu_generation_id,
      api_timeout_ms,
      cache_data,
      default_prices,
    } = input;
  
    let is_fallback_used = false;
    let fallback_source = '';
    let error_occurred = false;
    let error_type = '';
    let error_log = '';
    let notification_message = '';
    let optimized_menu: { items: OptimizedMenuItem[] } = { items: [] };
  
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), api_timeout_ms);
  
      try {
        const apiUrl = `https://api.supplier.local/v1/inventory?user_id=${user_id}&families=${family_ids.join(',')}`;
        const response = await fetch(apiUrl, {
          signal: controller.signal,
          method: 'GET',
          headers: { 'Content-Type': 'application/json' },
        });
  
        clearTimeout(timeoutId);
  
        if (!response.ok) {
          throw new Error(`API returned status ${response.status}`);
        }
  
        const apiData = await response.json();
        optimized_menu = {
          items: (apiData.items || []).map(
            (item: {
              ingredient_id: string;
              ingredient_name: string;
              current_price: number;
              stock_qty: number;
              discount_rate: number;
            }) => ({
              ingredient_id: item.ingredient_id,
              ingredient_name: item.ingredient_name,
              current_price: item.current_price,
              stock_qty: item.stock_qty,
              discount_rate: item.discount_rate,
            })
          ),
        };
  
        is_fallback_used = false;
        fallback_source = '';
        error_occurred = false;
        error_type = '';
        error_log = '';
        notification_message = '';
      } catch (fetchError) {
        clearTimeout(timeoutId);
  
        const errorMessage =
          fetchError instanceof Error ? fetchError.message : String(fetchError);
  
        if (
          errorMessage.includes('abort') ||
          errorMessage.includes('timeout') ||
          errorMessage.includes('AbortError')
        ) {
          error_type = 'api_timeout';
          error_log = `タイムアウト: API呼び出しが${api_timeout_ms}msで中断されました。フォールバック処理を実行します。`;
        } else {
          error_type = 'api_error';
          error_log = `API エラー: ${errorMessage}。フォールバック処理を実行します。`;
        }
  
        is_fallback_used = true;
        fallback_source = 'cache';
        error_occurred = true;
        notification_message = `キャッシュを使用してメニューを生成しています。`;
  
        optimized_menu = {
          items: (cache_data.items || []).map((item) => ({
            ingredient_id: item.ingredient_id,
            ingredient_name: item.ingredient_name,
            current_price: item.current_price,
            stock_qty: item.stock_qty,
            discount_rate: item.discount_rate,
          })),
        };
  
        if (optimized_menu.items.length === 0 && default_prices) {
          optimized_menu.items = Object.entries(default_prices).map(
            ([ingredient_id, price]) => ({
              ingredient_id,
              ingredient_name: ingredient_id,
              current_price: price,
              stock_qty: 0,
              discount_rate: 0,
            })
          );
          fallback_source = 'default_prices';
          notification_message = `デフォルト価格を使用してメニューを生成しています。`;
        }
      }
    } catch (unexpectedError) {
      error_occurred = true;
      error_type = 'system_error';
      error_log = `予期しないエラーが発生しました: ${
        unexpectedError instanceof Error
          ? unexpectedError.message
          : String(unexpectedError)
      }`;
      notification_message = `システムエラーが発生しました。`;
      is_fallback_used = true;
      fallback_source = 'cache';
      optimized_menu = {
        items: (cache_data.items || []).map((item) => ({
          ingredient_id: item.ingredient_id,
          ingredient_name: item.ingredient_name,
          current_price: item.current_price,
          stock_qty: item.stock_qty,
          discount_rate: item.discount_rate,
        })),
      };
    }
  
    return {
      is_fallback_used,
      fallback_source,
      optimized_menu,
      notification_message,
      error_log,
      error_occurred,
      error_type,
      system_crashed: false,
      menu_generation_id,
    };
  }
  return { fetchOptimalMenuWithFallback };
})();
export const fetchOptimalMenuWithFallback = __aivicBundle_12_fetchOptimalMenuWithFallback.fetchOptimalMenuWithFallback;
/* AIVIC_FUNCTION_BUNDLE_END owner=fetchOptimalMenuWithFallback */

