/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMealOptimizationScore exports=calculateMealOptimizationScore */
const __aivicBundle_14_calculateMealOptimizationScore = (() => {
  function calculateMealOptimizationScore(params: {
    ingredients: Array<{
      ingredient_id: string;
      ingredient_name: string;
      price: number;
      stock_fulfillment_rate: number;
    }>;
    season_priority_weight: number;
    discount_priority_weight: number;
    stock_priority_weight: number;
  }): {
    ranked_ingredients: Array<{
      ingredient_id: string;
      ingredient_name: string;
      optimization_score: number;
      stock_fulfillment_rate: number;
    }>;
    optimization_completed: boolean;
    ranking_basis: string;
  } {
    const { ingredients, season_priority_weight, discount_priority_weight, stock_priority_weight } = params;
  
    if (!ingredients || ingredients.length === 0) {
      return {
        ranked_ingredients: [],
        optimization_completed: true,
        ranking_basis: 'stock_fulfillment_rate',
      };
    }
  
    // グループ化: 価格ごとに食材をグループ分け
    const priceGroups = new Map<number, typeof ingredients>();
    for (const ingredient of ingredients) {
      const price = ingredient.price;
      if (!priceGroups.has(price)) {
        priceGroups.set(price, []);
      }
      priceGroups.get(price)!.push(ingredient);
    }
  
    // 各グループ内で在庫充足度でソート
    const sortedByPrice: typeof ingredients = [];
    const sortedPrices = Array.from(priceGroups.keys()).sort((a, b) => a - b);
  
    for (const price of sortedPrices) {
      const group = priceGroups.get(price)!;
      group.sort((a, b) => b.stock_fulfillment_rate - a.stock_fulfillment_rate);
      sortedByPrice.push(...group);
    }
  
    // 正規化された重みの合計
    const totalWeight = season_priority_weight + discount_priority_weight + stock_priority_weight;
    const normalizedSeasonWeight = season_priority_weight / totalWeight;
    const normalizedDiscountWeight = discount_priority_weight / totalWeight;
    const normalizedStockWeight = stock_priority_weight / totalWeight;
  
    // 最大在庫充足度を取得（正規化用）
    const maxStockFulfillment = Math.max(...ingredients.map(i => i.stock_fulfillment_rate));
    const minStockFulfillment = Math.min(...ingredients.map(i => i.stock_fulfillment_rate));
    const stockRange = maxStockFulfillment - minStockFulfillment || 1;
  
    // スコア計算
    const rankedIngredients = sortedByPrice.map((ingredient, index) => {
      // 在庫充足度の正規化スコア（0-100）
      const normalizedStockScore =
        ((ingredient.stock_fulfillment_rate - minStockFulfillment) / stockRange) * 100;
  
      // 旬度スコア（ここでは簡略化して50と仮定）
      const seasonScore = 50;
  
      // 割引スコア（ここでは簡略化して50と仮定）
      const discountScore = 50;
  
      // 加重平均でスコア計算
      const optimizationScore =
        normalizedSeasonWeight * seasonScore +
        normalizedDiscountWeight * discountScore +
        normalizedStockWeight * normalizedStockScore;
  
      return {
        ingredient_id: ingredient.ingredient_id,
        ingredient_name: ingredient.ingredient_name,
        optimization_score: Math.round(optimizationScore * 10) / 10,
        stock_fulfillment_rate: ingredient.stock_fulfillment_rate,
      };
    });
  
    return {
      ranked_ingredients: rankedIngredients,
      optimization_completed: true,
      ranking_basis: 'stock_fulfillment_rate',
    };
  }
  return { calculateMealOptimizationScore };
})();
export const calculateMealOptimizationScore = __aivicBundle_14_calculateMealOptimizationScore.calculateMealOptimizationScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMealOptimizationScore */

