/* AIVIC_FUNCTION_BUNDLE_START owner=extractLowestPriceVendor exports=extractLowestPriceVendor */
const __aivicBundle_16_extractLowestPriceVendor = (() => {
  function extractLowestPriceVendor(
    price_data: Array<{
      item_id: string;
      item_name: string;
      vendor_a_price: number;
      vendor_a_name: string;
      vendor_b_price: number;
      vendor_b_name: string;
      vendor_c_price: number;
      vendor_c_name: string;
      monthly_quantity: number;
    }>
  ): Array<{
    item_id: string;
    item_name: string;
    recommended_vendor: string;
    lowest_price: number;
    monthly_quantity: number;
  }> {
    return price_data.map((item) => {
      const prices = [
        { price: item.vendor_a_price, vendor: item.vendor_a_name },
        { price: item.vendor_b_price, vendor: item.vendor_b_name },
        { price: item.vendor_c_price, vendor: item.vendor_c_name },
      ];
  
      const lowestEntry = prices.reduce((min, current) =>
        current.price < min.price ? current : min
      );
  
      return {
        item_id: item.item_id,
        item_name: item.item_name,
        recommended_vendor: lowestEntry.vendor,
        lowest_price: lowestEntry.price,
        monthly_quantity: item.monthly_quantity,
      };
    });
  }
  return { extractLowestPriceVendor };
})();
export const extractLowestPriceVendor = __aivicBundle_16_extractLowestPriceVendor.extractLowestPriceVendor;
/* AIVIC_FUNCTION_BUNDLE_END owner=extractLowestPriceVendor */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateSavingsReport exports=aggregateSavingsReport */
const __aivicBundle_17_aggregateSavingsReport = (() => {
  function aggregateSavingsReport(
    savings_by_item: SavingsItem[]
  ): {
    report_period: string;
    report_month: string;
    total_monthly_savings_amount: number;
    savings_by_item: SavingsItem[];
    item_count: number;
    vendor_recommendations: VendorRecommendation[];
  } {
    const total_monthly_savings_amount = savings_by_item.reduce(
      (sum, item) => sum + item.item_savings_amount,
      0
    );
  
    const item_count = savings_by_item.length;
  
    const vendorMap = new Map<string, { items: string[]; itemNames: string[] }>();
  
    for (const item of savings_by_item) {
      const vendor = item.recommended_vendor;
      if (!vendorMap.has(vendor)) {
        vendorMap.set(vendor, { items: [], itemNames: [] });
      }
      const entry = vendorMap.get(vendor)!;
      entry.items.push(item.item_id);
      entry.itemNames.push(item.item_name);
    }
  
    const vendor_recommendations: VendorRecommendation[] = Array.from(
      vendorMap.entries()
    ).map(([vendor_name, data]) => ({
      vendor_name,
      recommended_items: data.items,
      item_names: data.itemNames,
    }));
  
    const now = new Date();
    const report_month = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  
    return {
      report_period: 'monthly',
      report_month,
      total_monthly_savings_amount,
      savings_by_item,
      item_count,
      vendor_recommendations,
    };
  }
  return { aggregateSavingsReport };
})();
export const aggregateSavingsReport = __aivicBundle_17_aggregateSavingsReport.aggregateSavingsReport;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateSavingsReport */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlyCostReductionWithFallback exports=calculateMonthlyCostReductionWithFallback */
const __aivicBundle_18_calculateMonthlyCostReductionWithFallback = (() => {
  async function calculateMonthlyCostReductionWithFallback(
    current_month_purchase_records: PurchaseRecord[],
    monthly_budget: number,
    previous_month_price_data: {
      item_id: string;
      item_name: string;
      previous_month_price: number;
      unit: string;
      price_history: number[];
    },
    current_month_cost: number
  ): Promise<{
    status: string;
    error_message: string;
    original_cost: number;
    fallback_proposed_cost: number;
    reduction_amount: number;
    reduction_percentage: number;
    proposal_items: Array<{
      item_id: string;
      item_name: string;
      quantity: number;
      current_unit_price: number;
      fallback_unit_price: number;
      potential_reduction: number;
      unit: string;
    }>;
    budget_status: string;
    budget_exceeded_amount: number;
    fallback_data_used: boolean;
    cache_timestamp: number[];
    notification_message: string;
  }> {
    const proposal_items: Array<{
      item_id: string;
      item_name: string;
      quantity: number;
      current_unit_price: number;
      fallback_unit_price: number;
      potential_reduction: number;
      unit: string;
    }> = [];
  
    let total_reduction_amount = 0;
  
    // 前月データを使用した代替提案ロジック
    for (const record of current_month_purchase_records) {
      if (
        record.item_id === previous_month_price_data.item_id &&
        record.unit_price > previous_month_price_data.previous_month_price
      ) {
        const fallback_unit_price = previous_month_price_data.previous_month_price;
        const quantity_in_base_unit = record.quantity;
        const current_total = record.unit_price * quantity_in_base_unit;
        const fallback_total = fallback_unit_price * quantity_in_base_unit;
        const potential_reduction = current_total - fallback_total;
  
        const item_name = (record as any).item_name || previous_month_price_data.item_name;
  
        proposal_items.push({
          item_id: record.item_id,
          item_name: item_name,
          quantity: record.quantity,
          current_unit_price: record.unit_price,
          fallback_unit_price: fallback_unit_price,
          potential_reduction: potential_reduction,
          unit: previous_month_price_data.unit,
        });
  
        total_reduction_amount += potential_reduction;
      }
    }
  
    const fallback_proposed_cost = current_month_cost - total_reduction_amount;
    const reduction_percentage =
      current_month_cost > 0
        ? Math.round((total_reduction_amount / current_month_cost) * 10000) /
          10000
        : 0;
  
    const budget_exceeded = fallback_proposed_cost > monthly_budget;
    const budget_exceeded_amount = budget_exceeded
      ? fallback_proposed_cost - monthly_budget
      : 0;
  
    const error_message =
      '価格データの取得に失敗しました。前月のデータを参考に提案を表示しています';
    const notification_message = error_message;
  
    return {
      status: 'fallback_applied',
      error_message: error_message,
      original_cost: current_month_cost,
      fallback_proposed_cost: fallback_proposed_cost,
      reduction_amount: total_reduction_amount,
      reduction_percentage: reduction_percentage,
      proposal_items: proposal_items,
      budget_status: budget_exceeded ? 'exceeded' : 'within_budget',
      budget_exceeded_amount: budget_exceeded_amount,
      fallback_data_used: true,
      cache_timestamp: previous_month_price_data.price_history,
      notification_message: notification_message,
    };
  }
  return { calculateMonthlyCostReductionWithFallback };
})();
export const calculateMonthlyCostReductionWithFallback = __aivicBundle_18_calculateMonthlyCostReductionWithFallback.calculateMonthlyCostReductionWithFallback;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMonthlyCostReductionWithFallback */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlySpendingReductionEffect exports=calculateMonthlySpendingReductionEffect */
const __aivicBundle_19_calculateMonthlySpendingReductionEffect = (() => {
  function calculateMonthlySpendingReductionEffect(params: {
    distributors: Array<{
      distributor_id: string;
      distributor_name: string;
      priority_order: number;
      price: number;
    }>;
    purchase_records: Array<{
      record_id: string;
      distributor_id: string;
      ingredient_name: string;
      quantity: number;
      unit_price: number;
      total_cost: number;
      purchase_date: string;
    }>;
    monthly_budget: number;
    analysis_month: string;
  }): {
    recommended_primary_distributor_id: string;
    recommended_primary_distributor_name: string;
    recommended_primary_priority_order: number;
    distributor_priority_list: Array<{
      distributor_id: string;
      distributor_name: string;
      priority_order: number;
      price: number;
    }>;
    monthly_report: {
      recommended_purchase_priority_order: string[];
    };
    total_monthly_purchase_cost: number;
    budget_achievement_rate: number;
    potential_reduction_amount: number;
    price_based_reduction_amount: number;
    optimized_total_cost_if_consolidated_to_top_priority: number;
  } {
    const {
      distributors,
      purchase_records,
      monthly_budget,
      analysis_month,
    } = params;
  
    // Validate analysis_month is provided and non-empty
    if (!String(analysis_month).trim()) {
      throw new Error("analysis_month is required");
    }
  
    // Sort distributors by priority_order to get the recommended primary distributor
    const sortedDistributors = [...distributors].sort(
      (a, b) => a.priority_order - b.priority_order
    );
  
    const recommendedPrimary = sortedDistributors[0];
  
    // Calculate total monthly purchase cost from all purchase records
    const totalMonthlyCost = purchase_records.reduce(
      (sum, record) => sum + record.total_cost,
      0
    );
  
    // Calculate budget achievement rate as percentage
    const budgetAchievementRate = Math.round(
      (totalMonthlyCost / monthly_budget) * 100
    );
  
    // Calculate potential reduction amount (unused budget)
    const potentialReduction = monthly_budget - totalMonthlyCost;
  
    // Build a map of ingredient prices by distributor
    const itemPricesByDistributor: {
      [key: string]: { [key: string]: number };
    } = {};
  
    distributors.forEach((dist) => {
      itemPricesByDistributor[dist.distributor_id] = {};
    });
  
    purchase_records.forEach((record) => {
      if (!itemPricesByDistributor[record.distributor_id]) {
        itemPricesByDistributor[record.distributor_id] = {};
      }
      itemPricesByDistributor[record.distributor_id][record.ingredient_name] =
        record.unit_price;
    });
  
    // Calculate what the cost would be if all purchases were made from the top priority distributor
    let optimizedCostIfConsolidated = 0;
  
    purchase_records.forEach((record) => {
      const topPriorityDistId = recommendedPrimary.distributor_id;
      const topDistributorPrice =
        itemPricesByDistributor[topPriorityDistId]?.[record.ingredient_name] ||
        record.unit_price;
  
      optimizedCostIfConsolidated += topDistributorPrice * record.quantity;
    });
  
    // Price-based reduction is the difference between current total and optimized total
    let priceBasedReduction = totalMonthlyCost - optimizedCostIfConsolidated;
  
    // Ensure price-based reduction is not negative
    if (priceBasedReduction < 0) {
      priceBasedReduction = 0;
    }
  
    // Build distributor priority list sorted by priority_order
    const distributorPriorityList = sortedDistributors.map((dist) => ({
      distributor_id: dist.distributor_id,
      distributor_name: dist.distributor_name,
      priority_order: dist.priority_order,
      price: dist.price,
    }));
  
    // Build recommended purchase priority order
    const recommendedPurchasePriorityOrder = sortedDistributors.map(
      (dist) => dist.distributor_id
    );
  
    return {
      recommended_primary_distributor_id: recommendedPrimary.distributor_id,
      recommended_primary_distributor_name: recommendedPrimary.distributor_name,
      recommended_primary_priority_order: recommendedPrimary.priority_order,
      distributor_priority_list: distributorPriorityList,
      monthly_report: {
        recommended_purchase_priority_order: recommendedPurchasePriorityOrder,
      },
      total_monthly_purchase_cost: totalMonthlyCost,
      budget_achievement_rate: budgetAchievementRate,
      potential_reduction_amount: potentialReduction,
      price_based_reduction_amount: priceBasedReduction,
      optimized_total_cost_if_consolidated_to_top_priority:
        optimizedCostIfConsolidated,
    };
  }
  return { calculateMonthlySpendingReductionEffect };
})();
export const calculateMonthlySpendingReductionEffect = __aivicBundle_19_calculateMonthlySpendingReductionEffect.calculateMonthlySpendingReductionEffect;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMonthlySpendingReductionEffect */

