/* AIVIC_FUNCTION_BUNDLE_START owner=aggregatePriceInventoryData exports=aggregatePriceInventoryData */
const __aivicBundle_21_aggregatePriceInventoryData = (() => {
  function aggregatePriceInventoryData(
    allSourcesData: Array<{
      supplierId?: string;
      supplierName?: string;
      supermarketId?: string;
      supermarketName?: string;
      itemId: string;
      itemName: string;
      price: number;
      quantity: number;
      updatedAt: Date;
    }>
  ) {
    const itemMap = new Map<
      string,
      {
        itemId: string;
        itemName: string;
        prices: Array<{ source: string; price: number }>;
        inventories: Array<{ source: string; quantity: number }>;
        latestUpdatedAt: Date;
      }
    >();
  
    for (const record of allSourcesData) {
      const key = record.itemId;
      if (!itemMap.has(key)) {
        itemMap.set(key, {
          itemId: record.itemId,
          itemName: record.itemName,
          prices: [],
          inventories: [],
          latestUpdatedAt: record.updatedAt,
        });
      }
  
      const item = itemMap.get(key)!;
      const sourceId = record.supplierId || record.supermarketId || '';
  
      item.prices.push({ source: sourceId, price: record.price });
      item.inventories.push({ source: sourceId, quantity: record.quantity });
  
      if (record.updatedAt > item.latestUpdatedAt) {
        item.latestUpdatedAt = record.updatedAt;
      }
    }
  
    const aggregatedItems = Array.from(itemMap.values()).map((item) => {
      const prices = item.prices;
      const priceValues = prices.map((p) => p.price);
      const averagePrice =
        priceValues.length > 0
          ? priceValues.reduce((a, b) => a + b, 0) / priceValues.length
          : 0;
      const minPrice =
        priceValues.length > 0 ? Math.min(...priceValues) : 0;
      const maxPrice =
        priceValues.length > 0 ? Math.max(...priceValues) : 0;
  
      const totalInventory = item.inventories.reduce(
        (sum, inv) => sum + inv.quantity,
        0
      );
  
      return {
        itemId: item.itemId,
        itemName: item.itemName,
        sourceCount: new Set(item.prices.map((p) => p.source)).size,
        prices: item.prices,
        averagePrice,
        minPrice,
        maxPrice,
        inventories: item.inventories,
        totalInventory,
        latestUpdatedAt: item.latestUpdatedAt,
      };
    });
  
    const uniqueSources = new Set(
      allSourcesData.map((d) => d.supplierId || d.supermarketId || '')
    );
    const totalSourcesProcessed = uniqueSources.size;
    const totalItemsAggregated = itemMap.size;
    const duplicateRecordCount = 0;
  
    return {
      aggregatedItems,
      metadata: {
        totalSourcesProcessed,
        totalItemsAggregated,
        aggregationTimestamp: new Date(),
        duplicateRecordCount,
        dataConsistencyStatus: 'consistent',
      },
    };
  }
  return { aggregatePriceInventoryData };
})();
export const aggregatePriceInventoryData: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_21_aggregatePriceInventoryData.aggregatePriceInventoryData as (...args: any[]) => any)(...args);
