/* AIVIC_FUNCTION_BUNDLE_START owner=fetchInventoryAndPriceData exports=fetchInventoryAndPriceData */
const __aivicBundle_23_fetchInventoryAndPriceData = (() => {
  async function fetchInventoryAndPriceData(
    material_ids: string[]
  ): Promise<InventoryFetchResult> {
    const processed_count = material_ids.length;
    const errors: Array<{
      material_id: string;
      status_code: number;
      message: string;
    }> = [];
    const data: Array<{
      material_id: string;
      material_name: string;
      unit_price: number;
      inventory_count: number;
      distributor_id: string;
    }> = [];
    const warnings: string[] = [];
  
    for (const material_id of material_ids) {
      try {
        const response = await fetch(
          `https://api.distributor.local/inventory/${material_id}`
        );
        const responseBody = await response.json();
  
        if (!response.ok) {
          errors.push({
            material_id,
            status_code: response.status,
            message: responseBody.message || "Unknown error",
          });
          if (responseBody.inventory_count === 0) {
            warnings.push("在庫データなし");
          }
          continue;
        }
  
        if (
          responseBody.inventory_count === 0 ||
          responseBody.inventory_count === undefined
        ) {
          errors.push({
            material_id,
            status_code: 400,
            message: "食材が存在しません",
          });
          warnings.push("在庫データなし");
          continue;
        }
  
        data.push({
          material_id: responseBody.material_id,
          material_name: responseBody.material_name,
          unit_price: responseBody.unit_price,
          inventory_count: responseBody.inventory_count,
          distributor_id: responseBody.distributor_id,
        });
      } catch (error) {
        errors.push({
          material_id,
          status_code: 500,
          message:
            error instanceof Error ? error.message : "Internal server error",
        });
      }
    }
  
    const success_count = data.length;
    const error_count = errors.length;
    const status =
      error_count === 0
        ? "success"
        : error_count > 0 && success_count > 0
          ? "completed_with_errors"
          : "failed";
  
    return {
      processed_count,
      success_count,
      error_count,
      errors,
      data,
      warnings,
      status,
    };
  }
  return { fetchInventoryAndPriceData };
})();
export const fetchInventoryAndPriceData = __aivicBundle_23_fetchInventoryAndPriceData.fetchInventoryAndPriceData;
/* AIVIC_FUNCTION_BUNDLE_END owner=fetchInventoryAndPriceData */

