const __aivicBundle_33_encryptSensitiveData = (() => {
  function encryptSensitiveData(payload: {
    recordId?: string;
    userId: string;
    email: string;
    expenseHistory: Array<{ date: string; amount: number }>;
    timestamp: Date;
  }): EncryptionResult {
    const encryptionKeyId = randomUUID();
    
    const dataToEncrypt = {
      userId: payload.userId,
      email: payload.email,
      expenseHistory: payload.expenseHistory,
      timestamp: payload.timestamp.toISOString(),
      recordId: payload.recordId || null,
    };
    
    const jsonString = JSON.stringify(dataToEncrypt);
    const encryptedData = Buffer.from(jsonString).toString("base64");
    
    const hash = createHash("sha256")
      .update(jsonString + encryptionKeyId)
      .digest("hex");
    
    return {
      encrypted: true,
      encryptedData: encryptedData,
      dataHash: hash,
      encryptionKeyId: encryptionKeyId,
    };
  }
  return { encryptSensitiveData };
})();
