const __aivicBundle_42_evaluateExternalFactorTrustworthiness = (() => {
  function evaluateExternalFactorTrustworthiness(params: {
    external_factor_data?: {
      data_source_id: string;
      data_source_type: string;
      data_source_name?: string;
      collected_at?: string;
      [key: string]: unknown;
    };
    trustworthiness_score: number;
    adoption_criteria_threshold: number;
    externalFactors?: ExternalFactorDataSource[];
    historicalAccuracy?: Record<string, number>;
    dataSourceReliability?: Record<string, number>;
  }): {
    data_source_id?: string;
    data_source_type?: string;
    assigned_trustworthiness_score: number;
    adoption_criteria_threshold: number;
    meets_adoption_criteria: boolean;
    is_selected_for_prediction_model_input: boolean;
    adoption_decision: string;
    trustScores?: Record<string, number>;
    overallTrustScore?: number;
    unreliableSources?: string[];
  } {
    const {
      external_factor_data,
      trustworthiness_score,
      adoption_criteria_threshold,
      externalFactors,
      historicalAccuracy = {},
      dataSourceReliability = {},
    } = params;
  
    // Handle single external_factor_data case (test scenario)
    if (external_factor_data) {
      const meetsAdoptionCriteria =
        trustworthiness_score >= adoption_criteria_threshold;
      const adoptionDecision = meetsAdoptionCriteria ? 'ADOPTED' : 'REJECTED';
  
      return {
        data_source_id: external_factor_data.data_source_id,
        data_source_type: external_factor_data.data_source_type,
        assigned_trustworthiness_score: trustworthiness_score,
        adoption_criteria_threshold,
        meets_adoption_criteria: meetsAdoptionCriteria,
        is_selected_for_prediction_model_input: meetsAdoptionCriteria,
        adoption_decision: adoptionDecision,
      };
    }
  
    // Handle multiple externalFactors case (plan scenario)
    if (externalFactors && externalFactors.length > 0) {
      const trustScores: Record<string, number> = {};
      let totalTrustScore = 0;
      const unreliableSources: string[] = [];
      const UNRELIABLE_THRESHOLD = 60;
  
      for (const factor of externalFactors) {
        const sourceId = factor.sourceId;
        const historicalAcc = historicalAccuracy[sourceId] ?? 0.5;
        const reliability = dataSourceReliability[sourceId] ?? 0.5;
  
        // Calculate trust score as weighted average of historical accuracy and reliability
        // Convert to 0-100 scale
        const calculatedTrustScore = Math.round(
          (historicalAcc * 0.6 + reliability * 0.4) * 100
        );
        trustScores[sourceId] = calculatedTrustScore;
        totalTrustScore += calculatedTrustScore;
  
        if (calculatedTrustScore < UNRELIABLE_THRESHOLD) {
          unreliableSources.push(sourceId);
        }
      }
  
      const overallTrustScore =
        externalFactors.length > 0
          ? Math.round(totalTrustScore / externalFactors.length)
          : 0;
  
      return {
        assigned_trustworthiness_score: overallTrustScore,
        adoption_criteria_threshold,
        meets_adoption_criteria: overallTrustScore >= adoption_criteria_threshold,
        is_selected_for_prediction_model_input:
          overallTrustScore >= adoption_criteria_threshold,
        adoption_decision:
          overallTrustScore >= adoption_criteria_threshold
            ? 'ADOPTED'
            : 'REJECTED',
        trustScores,
        overallTrustScore,
        unreliableSources,
      };
    }
  
    // Default case when no data is provided
    return {
      assigned_trustworthiness_score: trustworthiness_score,
      adoption_criteria_threshold,
      meets_adoption_criteria:
        trustworthiness_score >= adoption_criteria_threshold,
      is_selected_for_prediction_model_input:
        trustworthiness_score >= adoption_criteria_threshold,
      adoption_decision:
        trustworthiness_score >= adoption_criteria_threshold
          ? 'ADOPTED'
          : 'REJECTED',
      trustScores: {},
      overallTrustScore: trustworthiness_score,
      unreliableSources: [],
    };
  }
  return { evaluateExternalFactorTrustworthiness };
})();
