/* AIVIC_FUNCTION_BUNDLE_START owner=acquireExternalFactorDataWithTrustScore exports=acquireExternalFactorDataWithTrustScore */
const __aivicBundle_44_acquireExternalFactorDataWithTrustScore = (() => {
  function acquireExternalFactorDataWithTrustScore(params: {
    targetDate?: Date;
    dataSourceConnections?: {
      fetchWeatherData?: () => any;
      fetchPriceIndex?: () => any;
      fetchEventInfo?: () => any;
      fetchCompetitorSale?: () => any;
    };
    requiredFactorTypes?: string[];
    factorTypes?: string[];
    startDate?: string;
    endDate?: string;
    minimumTrustThreshold?: number;
  }): {
    acquiredData: (ExternalFactorDataSource & { trustScore: number })[];
    trustScoreDistribution: Record<string, number>;
    acquisitionStatus: string;
  } {
    const {
      targetDate,
      dataSourceConnections,
      requiredFactorTypes,
      factorTypes,
      minimumTrustThreshold,
    } = params;
  
    const effectiveFactorTypes = requiredFactorTypes || factorTypes || [];
    const effectiveMinimumTrust = minimumTrustThreshold ?? 0;
  
    if (!dataSourceConnections) {
      return {
        acquiredData: [],
        trustScoreDistribution: {},
        acquisitionStatus: "no_data_source",
      };
    }
  
    const acquiredData: (ExternalFactorDataSource & { trustScore: number })[] =
      [];
    const trustScores: number[] = [];
  
    for (const factorType of effectiveFactorTypes) {
      let fetchFn: (() => any) | undefined;
      let trustScoreBase = 0;
  
      if (factorType === "weather" && dataSourceConnections.fetchWeatherData) {
        fetchFn = dataSourceConnections.fetchWeatherData;
        trustScoreBase = 85;
      } else if (
        factorType === "priceIndex" &&
        dataSourceConnections.fetchPriceIndex
      ) {
        fetchFn = dataSourceConnections.fetchPriceIndex;
        trustScoreBase = 80;
      } else if (
        factorType === "event" &&
        dataSourceConnections.fetchEventInfo
      ) {
        fetchFn = dataSourceConnections.fetchEventInfo;
        trustScoreBase = 90;
      } else if (
        factorType === "competitor_sale" &&
        dataSourceConnections.fetchCompetitorSale
      ) {
        fetchFn = dataSourceConnections.fetchCompetitorSale;
        trustScoreBase = 75;
      }
  
      if (fetchFn) {
        try {
          const syncResult = fetchFn();
  
          if (syncResult instanceof Promise) {
            throw new Error(
              "データソース接続エラー: 非同期関数は同期実行できません"
            );
          }
  
          const trustScore = Math.min(100, trustScoreBase);
  
          if (trustScore >= effectiveMinimumTrust) {
            const dataItem: ExternalFactorDataSource & { trustScore: number } = {
              dataType: factorType,
              date: targetDate
                ? new Date(targetDate).toISOString()
                : new Date().toISOString(),
              value: syncResult?.value ?? syncResult ?? "",
              sourceId: syncResult?.sourceId ?? `source_${factorType}`,
              trustScore: Math.round(trustScore),
              lastUpdated: new Date(),
            };
  
            acquiredData.push(dataItem);
            trustScores.push(Math.round(trustScore));
          }
        } catch (error) {
          const errorMessage =
            error instanceof Error ? error.message : "不明なエラー";
  
          if (
            errorMessage.includes("接続エラー") ||
            errorMessage.includes("Connection error") ||
            errorMessage.includes("非同期関数")
          ) {
            throw error;
          }
        }
      }
    }
  
    const trustScoreDistribution: Record<string, number> = {
      "0-10": 0,
      "10-20": 0,
      "20-30": 0,
      "30-40": 0,
      "40-50": 0,
      "50-60": 0,
      "60-70": 0,
      "70-80": 0,
      "80-90": 0,
      "90-100": 0,
    };
  
    for (const score of trustScores) {
      const bucket = Math.floor(score / 10) * 10;
      const key = `${bucket}-${bucket + 10}`;
      if (key in trustScoreDistribution) {
        trustScoreDistribution[key]++;
      }
    }
  
    const acquisitionStatus =
      acquiredData.length > 0 ? "success" : "no_data_acquired";
  
    return {
      acquiredData,
      trustScoreDistribution,
      acquisitionStatus,
    };
  }
  return { acquireExternalFactorDataWithTrustScore };
})();
export const acquireExternalFactorDataWithTrustScore: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_44_acquireExternalFactorDataWithTrustScore.acquireExternalFactorDataWithTrustScore as (...args: any[]) => any)(...args);
/* AIVIC_FUNCTION_BUNDLE_END owner=acquireExternalFactorDataWithTrustScore */

