    // Merge discount thresholds
    const existingDiscounts = ruleSpec.discount_thresholds || [];
    const mergedDiscountThresholds = [
      ...existingDiscounts,
      ...discountThresholdsInput
    ].reduce((acc: any[], threshold: any) => {
      const existing = acc.find((t: any) => t.discount_id === threshold.discount_id);
      if (!existing) {
        acc.push(threshold);
      }
      return acc;
    }, []);
  
    // Merge sales periods
