/* AIVIC_FUNCTION_BUNDLE_START owner=detectConflictingDiscountRules exports=detectConflictingDiscountRules */
const __aivicBundle_47_detectConflictingDiscountRules = (() => {
  function detectConflictingDiscountRules(
    existingRules: any[],
    newRule: any
  ): { has_conflict: boolean; conflicting_rules: any[] } {
    const conflicts: any[] = [];
  
    for (const existingRule of existingRules) {
      // Check if same seasonal pattern
      if (existingRule.seasonal_pattern === newRule.seasonal_pattern) {
        // Check for discount rate overlap
        const existingMin = existingRule.discount_rate_min;
        const existingMax = existingRule.discount_rate_max;
        const newMin = newRule.discount_rate_min;
        const newMax = newRule.discount_rate_max;
  
        // Ranges overlap if: newMin <= existingMax AND newMax >= existingMin
        const discountRatesOverlap =
          newMin <= existingMax && newMax >= existingMin;
  
        if (discountRatesOverlap) {
          throw new Error(
            `割引率の範囲が既存ルール(${existingRule.rule_id})と競合しています`
          );
        }
  
        // Check for sales period overlap
        const existingStart = new Date(existingRule.sales_period_start);
        const existingEnd = new Date(existingRule.sales_period_end);
        const newStart = new Date(newRule.sales_period_start);
        const newEnd = new Date(newRule.sales_period_end);
  
        // Periods overlap if: newStart <= existingEnd AND newEnd >= existingStart
        const periodsOverlap =
          newStart <= existingEnd && newEnd >= existingStart;
  
        if (periodsOverlap && discountRatesOverlap) {
          throw new Error(
            `販売期間が既存ルール(${existingRule.rule_id})と競合しています`
          );
        }
  
        if (periodsOverlap) {
          throw new Error(
            `販売期間が既存ルール(${existingRule.rule_id})と競合しています`
          );
        }
      }
    }
  
    return {
      has_conflict: false,
      conflicting_rules: conflicts,
    };
  }
  return { detectConflictingDiscountRules };
})();
export const detectConflictingDiscountRules = __aivicBundle_47_detectConflictingDiscountRules.detectConflictingDiscountRules;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectConflictingDiscountRules */

